def ax3(fig,pos,x,title,colors,s=15):
 ax=fig.add_subplot(*pos,projection='3d');p=x*1e3;artist=ax.scatter(*p.T,c=colors,s=s,depthshade=False,edgecolors='none');ax._state_artist=artist;ax.view_init(elev=17,azim=-55);ax.set(xlabel='X (mm)',ylabel='Y (mm)',zlabel='Z (mm)',title=title);ax.set_box_aspect(np.maximum(np.ptp(p,axis=0),.1));ax.tick_params(labelsize=9);return ax
